                                        Icons.Default.LockOpen
                                    else
                                        Icons.Default.Block,
                                    contentDescription = null
                                )
                            },
                            onClick = {
                                menuExpanded = false
                                onToggleBlocked()
                            }
                        )
                        DropdownMenuItem(
