@Composable
private fun AppDrawer(
    favorites: List<SavedLocation>,
    activeId: String?,
    navConfig: List<com.crome.forecastpoint.data.DrawerNavConfigItem>,
    onNavOrderChange: (List<String>) -> Unit,
    onForecast: () -> Unit,
    onCurrentLocation: () -> Unit,
    onAddCity: () -> Unit,
    onMap: () -> Unit,
    onSun: () -> Unit,
    onMoon: () -> Unit,
    onSpaceWeather: () -> Unit,
    onEarthquakes: () -> Unit,
    onStorms: () -> Unit,
    onSelectFavorite: (SavedLocation) -> Unit,
    onRenameFavorite: (SavedLocation) -> Unit,
    onRemoveFavorite: (SavedLocation) -> Unit,
    onFavoritesOrderChange: (List<String>) -> Unit,
    onSettings: () -> Unit,
    onAbout: () -> Unit,
) {
    val actions = mapOf(
        "Forecast" to onForecast,
        "CurrentLocation" to onCurrentLocation,
        "Map" to onMap,
        "Sun" to onSun,
        "Moon" to onMoon,
        "SpaceWeather" to onSpaceWeather,
        "Earthquakes" to onEarthquakes,
        "Storms" to onStorms,
        "AddCity" to onAddCity,
    )
    val icons = mapOf(
        "Forecast" to Icons.AutoMirrored.Filled.List,
        "CurrentLocation" to Icons.Filled.MyLocation,
        "Map" to Icons.Filled.Map,
        "Sun" to Icons.Filled.WbSunny,
        "Moon" to Icons.Filled.DarkMode,
        "SpaceWeather" to Icons.Filled.Bolt,
        "Earthquakes" to Icons.Filled.Public,
        "Storms" to Icons.Filled.Thunderstorm,
        "AddCity" to Icons.Filled.Add,
    )

    // Visible items only (Settings controls which appear)
    val visibleIds = remember(navConfig) {
        navConfig.filter { it.enabled }.map { it.id }
    }
    // Local reorder state — do NOT re-key pointerInput on every swap (that cancels the drag)
    var order by remember { mutableStateOf(visibleIds) }
    val density = LocalDensity.current
    val rowHeightPx = with(density) { 38.dp.toPx() }
    var draggingIndex by remember { mutableIntStateOf(-1) }
    var dragOffsetY by remember { mutableFloatStateOf(0f) }
    // Snapshot of order when drag starts; commit on end
    var dragStartOrder by remember { mutableStateOf(order) }
    LaunchedEffect(visibleIds) {
        if (draggingIndex < 0 && visibleIds != order) order = visibleIds
    }

    ModalDrawerSheet(
        modifier = Modifier.width(300.dp),
        drawerContainerColor = SurfaceDark,
    ) {
        Column(
            Modifier
                .fillMaxHeight()
                .background(SurfaceDark),
        ) {
            Row(
                Modifier
                    .fillMaxWidth()
                    .background(PrimaryBlue)
                    .padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(
                    Icons.Filled.WbSunny,
                    contentDescription = null,
                    tint = Color.White,
                    modifier = Modifier.size(28.dp),
                )
                Spacer(Modifier.width(8.dp))
                Text(
                    "Point Forecast",
                    color = Color.White,
                    fontSize = 17.sp,
                    fontWeight = FontWeight.Bold,
                )
            }

            Text(
                "Long-press & drag to reorder · visibility in Settings",
                color = Color(0xFF90A4AE),
                fontSize = 10.sp,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            )

            // Nav items in a fixed Column (not LazyColumn) so reorders don't reset drag
            Column(Modifier.fillMaxWidth()) {
                order.forEachIndexed { index, id ->
                    key(id) {
                        val isDragging = index == draggingIndex
                        val icon = icons[id] ?: Icons.Filled.Menu
                        val label = PreferencesRepository.drawerNavDisplayName(id)
                        val onClick = actions[id] ?: {}
                        Row(
                            Modifier
                                .fillMaxWidth()
                                .height(38.dp)
                                .zIndex(if (isDragging) 2f else 0f)
                                .offset {
                                    IntOffset(
                                        x = 0,
                                        y = if (isDragging) dragOffsetY.roundToInt() else 0,
                                    )
                                }
                                .background(
                                    if (isDragging) Color(0xFF37474F) else Color.Transparent,
                                )
                                .pointerInput(Unit) {
                                    // Stable key() + Unit keeps the gesture alive across reorders
                                    detectDragGesturesAfterLongPress(
                                        onDragStart = {
                                            val idx = order.indexOf(id)
                                            if (idx < 0) return@detectDragGesturesAfterLongPress
                                            draggingIndex = idx
                                            dragOffsetY = 0f
                                            dragStartOrder = order
                                        },
                                        onDragCancel = {
                                            order = dragStartOrder
                                            draggingIndex = -1
                                            dragOffsetY = 0f
                                        },
                                        onDragEnd = {
                                            draggingIndex = -1
                                            dragOffsetY = 0f
                                            onNavOrderChange(order)
                                        },
                                        onDrag = { change, dragAmount ->
                                            change.consume()
                                            val from = draggingIndex
                                            if (from < 0) return@detectDragGesturesAfterLongPress
                                            dragOffsetY += dragAmount.y
                                            val shift = (dragOffsetY / rowHeightPx).toInt()
                                            if (shift != 0) {
                                                val to = (from + shift).coerceIn(0, order.lastIndex)
                                                if (to != from) {
                                                    val next = order.toMutableList()
                                                    val item = next.removeAt(from)
                                                    next.add(to, item)
                                                    order = next
                                                    draggingIndex = to
                                                    dragOffsetY -= shift * rowHeightPx
                                                }
                                            }
                                        },
                                    )
                                }
                                .clickable(enabled = draggingIndex < 0, onClick = onClick)
                                .padding(horizontal = 6.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Icon(
                                Icons.Filled.DragHandle,
                                contentDescription = "Drag to reorder",
                                tint = Color(0xFF78909C),
                                modifier = Modifier.size(16.dp),
                            )
                            Spacer(Modifier.width(4.dp))
                            Icon(
                                icon,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(20.dp),
                            )
                            Spacer(Modifier.width(10.dp))
                            Text(
                                label,
                                color = Color.White,
                                fontSize = 14.sp,
                                modifier = Modifier.weight(1f),
                            )
                        }
                    }
                }
            }

            HorizontalDivider(
                color = Color(0xFF37474F),
                modifier = Modifier.padding(vertical = 2.dp),
            )

            HorizontalDivider(
                color = Color(0xFF37474F),
                modifier = Modifier.padding(vertical = 2.dp),
            )

            // Saved cities: same layout as menu rows above (plain Column, NO verticalScroll).
            // Scroll parents cancel long-press before drag can start.
            val favoriteIds = remember(favorites) { favorites.map { it.id } }
            var cityOrder by remember { mutableStateOf(favoriteIds) }
            val cityRowHeightPx = with(density) { 40.dp.toPx() }
            var cityDraggingIndex by remember { mutableIntStateOf(-1) }
            var cityDragOffsetY by remember { mutableFloatStateOf(0f) }
            var cityDragStartOrder by remember { mutableStateOf(cityOrder) }
            LaunchedEffect(favoriteIds) {
                if (cityDraggingIndex < 0 && favoriteIds != cityOrder) cityOrder = favoriteIds
            }
            val favoritesById = remember(favorites) { favorites.associateBy { it.id } }

            if (cityOrder.isNotEmpty()) {
                Text(
                    "Saved cities",
                    color = Color(0xFF90A4AE),
                    fontSize = 11.sp,
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
                )
                Text(
                    "Long-press & drag to reorder",
                    color = Color(0xFF607D8B),
                    fontSize = 10.sp,
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 0.dp),
                )
            } else {
                Text(
                    "No saved cities yet.\nTap Add City to search.",
                    color = Color(0xFF90A4AE),
                    fontSize = 12.sp,
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
                )
            }

            Column(Modifier.fillMaxWidth()) {
                cityOrder.forEach { id ->
                    val loc = favoritesById[id]
                    if (loc == null) return@forEach
                    key(id) {
                        val isDragging = cityOrder.indexOf(id) == cityDraggingIndex
                        Row(
                            Modifier
                                .fillMaxWidth()
                                .height(40.dp)
                                .zIndex(if (isDragging) 2f else 0f)
                                .offset {
                                    IntOffset(
                                        x = 0,
                                        y = if (isDragging) cityDragOffsetY.roundToInt() else 0,
                                    )
                                }
                                .background(
                                    when {
                                        isDragging -> Color(0xFF37474F)
                                        loc.id == activeId -> Color(0xFF37474F)
                                        else -> Color.Transparent
                                    },
                                )
                                .pointerInput(Unit) {
                                    detectDragGesturesAfterLongPress(
                                        onDragStart = {
                                            val idx = cityOrder.indexOf(id)
                                            if (idx < 0) return@detectDragGesturesAfterLongPress
                                            cityDraggingIndex = idx
                                            cityDragOffsetY = 0f
                                            cityDragStartOrder = cityOrder
                                        },
                                        onDragCancel = {
                                            cityOrder = cityDragStartOrder
                                            cityDraggingIndex = -1
                                            cityDragOffsetY = 0f
                                        },
                                        onDragEnd = {
                                            cityDraggingIndex = -1
                                            cityDragOffsetY = 0f
                                            onFavoritesOrderChange(cityOrder)
                                        },
                                        onDrag = { change, dragAmount ->
                                            change.consume()
                                            val from = cityDraggingIndex
                                            if (from < 0) return@detectDragGesturesAfterLongPress
                                            cityDragOffsetY += dragAmount.y
                                            val shift =
                                                (cityDragOffsetY / cityRowHeightPx).toInt()
                                            if (shift != 0) {
                                                val to = (from + shift)
                                                    .coerceIn(0, cityOrder.lastIndex)
                                                if (to != from) {
                                                    val next = cityOrder.toMutableList()
                                                    val item = next.removeAt(from)
                                                    next.add(to, item)
                                                    cityOrder = next
                                                    cityDraggingIndex = to
                                                    cityDragOffsetY -= shift * cityRowHeightPx
                                                }
                                            }
                                        },
                                    )
                                }
                                .clickable(enabled = cityDraggingIndex < 0) {
                                    onSelectFavorite(loc)
                                }
                                .padding(start = 4.dp, end = 2.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Icon(
                                Icons.Filled.DragHandle,
                                contentDescription = "Drag to reorder",
                                tint = Color(0xFF78909C),
                                modifier = Modifier.size(16.dp),
                            )
                            Spacer(Modifier.width(4.dp))
                            Icon(
                                Icons.Filled.Star,
